def trig_mean_dir(l_, items, qoffs=(0,1,2)):
    D_=[]; Nn=[]; Al=[]
    for i_ in items:
        for qo in qoffs:
            w_ = xt(l_,4*i_+2,info1[i_]['dp']-qo); n_ = xt(l_,4*i_,info1[i_]['dpn']-qo)
            D_.append(w_-n_); Nn.append(n_); Al += [w_, n_]
    md = np.mean(D_,0); b = md/np.linalg.norm(md); Nn = np.array(Nn); Al = np.array(Al)
    m_r = Al.mean(0); a_c = m_r/(m_r@m_r)
