def head_W(W, h): return W[h*256:(h+1)*256].numpy().astype(np.float64)
def addon(Wfull, D2, protect):
    """Return new full W (torch) with projector I - B^T (D B^T)^-1 D applied to each head; B = D2 minus projection on 'protect' rows (orthonormalised)."""
    Wn_ = Wfull.clone().numpy().astype(np.float64); gains = []
    for h in range(4):
        Pm = protect[h] if isinstance(protect, dict) else protect
        Qb, _ = np.linalg.qr(Pm.T)            # orthonormal basis of protected space (256 x r)
        B = D2 - (D2 @ Qb) @ Qb.T
        M = D2 @ B.T
        gains.append(np.linalg.norm(B, axis=1).max() / np.abs(np.linalg.det(M))**(1/len(D2)) if len(D2) else 0)
        Wh = Wn_[h*256:(h+1)*256]
        Wn_[h*256:(h+1)*256] = Wh - B.T @ np.linalg.solve(M, D2 @ Wh)
    return torch.tensor(Wn_).float(), gains
