    for h in range(4):
        C=sum(wts[g]*ST[h][g][0] for g in wts); C=C+lam*torch.trace(C)/256*torch.eye(256,dtype=torch.double)
        d=DK[h]
        G=[d]+[ST[h][g][1] for g in zero if g in ('T','E')]+([torch.tensor(NULL12[h][k]).double() for k in range(2)] if 'null' in zero else [])
        G=torch.stack(G,1); f=torch.zeros(G.shape[1],dtype=torch.double); f[0]=1
